namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeSubmission
{
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private readonly Dictionary<int, List<int>> _ratings = new();
    private int _nextId;

    public RecipeService()
    {
        _recipes = new List<Recipe>
        {
            new() { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian", Ingredients = "Pizza dough
Mozzarella cheese
Fresh basil
San Marzano tomatoes
Olive oil
Salt", Steps = "1. Preheat oven to 475°F
2. Roll out dough on floured surface
3. Spread crushed tomatoes evenly
4. Add torn mozzarella pieces
5. Bake for 10-12 minutes
6. Top with fresh basil and drizzle olive oil" },
            new() { Id = 2, Title = "Spaghetti Carbonara", Category = "Italian", Ingredients = "Spaghetti
Guanciale or pancetta
Eggs
Pecorino Romano
Black pepper", Steps = "1. Cook spaghetti in salted water
2. Fry guanciale until crispy
3. Whisk eggs with grated pecorino and pepper
4. Toss hot pasta with guanciale
5. Remove from heat and stir in egg mixture
6. Serve immediately with extra pecorino" },
            new() { Id = 3, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken thighs
Yogurt
Garam masala
Turmeric
Crushed tomatoes
Heavy cream
Garlic and ginger
Onion", Steps = "1. Marinate chicken in yogurt and spices for 2 hours
2. Grill or broil chicken until charred
3. Sauté onion, garlic, and ginger
4. Add tomatoes and simmer 15 minutes
5. Stir in cream and spices
6. Add chicken pieces and simmer 10 minutes" },
            new() { Id = 4, Title = "Vegetable Pad Thai", Category = "Thai", Ingredients = "Rice noodles
Tofu
Bean sprouts
Green onions
Peanuts
Lime
Tamarind paste
Fish sauce
Sugar
Eggs", Steps = "1. Soak rice noodles in warm water 30 minutes
2. Make sauce: tamarind, fish sauce, sugar
3. Fry pressed tofu until golden
4. Scramble eggs in wok
5. Add noodles and sauce, toss until coated
6. Top with peanuts, bean sprouts, and lime" },
            new() { Id = 5, Title = "Beef Tacos", Category = "Mexican", Ingredients = "Ground beef
Taco seasoning
Corn tortillas
Cilantro
Onion
Lime
Salsa
Avocado", Steps = "1. Brown ground beef in skillet
2. Add taco seasoning and water, simmer 5 minutes
3. Warm tortillas on dry pan
4. Dice onion and cilantro for topping
5. Assemble tacos with meat and toppings
6. Squeeze lime over and add salsa" },
            new() { Id = 6, Title = "Miso Ramen", Category = "Japanese", Ingredients = "Ramen noodles
Miso paste
Pork belly
Soft-boiled eggs
Green onions
Nori
Chicken broth
Soy sauce
Garlic", Steps = "1. Simmer broth with garlic for 30 minutes
2. Whisk in miso paste off heat
3. Sear sliced pork belly until caramelized
4. Cook ramen noodles according to package
5. Assemble bowls: noodles, broth, pork
6. Top with halved egg, nori, and green onions" },
            new() { Id = 7, Title = "Guacamole", Category = "Mexican", Ingredients = "Avocados
Lime juice
Cilantro
Red onion
Jalapeño
Tomato
Salt", Steps = "1. Halve and pit ripe avocados
2. Mash to desired consistency
3. Finely dice onion, jalapeño, and tomato
4. Mix all ingredients together
5. Add lime juice and salt to taste
6. Serve immediately with tortilla chips" },
            new() { Id = 8, Title = "Butter Chicken", Category = "Indian", Ingredients = "Chicken breast
Butter
Tomato puree
Heavy cream
Garam masala
Chili powder
Garlic
Ginger
Fenugreek leaves", Steps = "1. Marinate chicken in yogurt and spices
2. Grill or pan-fry chicken pieces
3. Melt butter and sauté garlic, ginger
4. Add tomato puree and spices, simmer
5. Stir in cream and fenugreek
6. Add chicken and simmer until thick" },
        };
        _nextId = 9;

        _ratings[1] = new List<int> { 5, 4, 5 };
        _ratings[2] = new List<int> { 4, 5, 4, 5 };
        _ratings[3] = new List<int> { 5, 5, 4 };
        _ratings[4] = new List<int> { 4, 3, 4 };
        _ratings[5] = new List<int> { 5, 4, 5, 4 };
        _ratings[6] = new List<int> { 5, 5, 5 };
        _ratings[7] = new List<int> { 4, 4, 3 };
        _ratings[8] = new List<int> { 5, 4, 5, 5 };

        foreach (var recipe in _recipes)
        {
            if (_ratings.TryGetValue(recipe.Id, out var ratings))
            {
                recipe.RatingCount = ratings.Count;
                recipe.AverageRating = ratings.Average();
            }
        }
    }

    public IReadOnlyList<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();
    }

    public IReadOnlyList<Recipe> GetRecipesByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetRecipeById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        if (stars < 1 || stars > 5) return;

        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is null) return;

        if (!_ratings.ContainsKey(recipeId))
            _ratings[recipeId] = new List<int>();

        _ratings[recipeId].Add(stars);
        recipe.RatingCount = _ratings[recipeId].Count;
        recipe.AverageRating = _ratings[recipeId].Average();
    }

    public void SubmitRecipe(RecipeSubmission submission)
    {
        var recipe = new Recipe
        {
            Id = _nextId++,
            Title = submission.Title,
            Category = submission.Category,
            Ingredients = submission.Ingredients,
            Steps = submission.Steps
        };
        _recipes.Add(recipe);
    }
}

