@using RecipeShare.Services
@inject RecipeService RecipeService
@rendermode InteractiveServer

<div class="d-inline-block">
    <span class="me-2">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span role="button" class="fs-4" style="cursor: pointer; color: @(star <= selectedRating ? "#ffc107" : "#dee2e6")"
                  @onclick="() => Rate(star)"
                  title="Rate @star star(s)">★</span>
        }
    </span>
    <span class="text-muted">
        @if (RatingCount > 0)
        {
            @($"{CurrentRating:F1} ({RatingCount} ratings)")
        }
        else
        {
            <text>Be the first to rate!</text>
        }
    </span>
    @if (rated)
    {
        <span class="text-success ms-2">Thanks for rating!</span>
    }
</div>

