@page "/submit"
@using RecipeShare.Services
@using RecipeShare.Models
@rendermode InteractiveServer
@inject RecipeService RecipeService

<PageTitle>Submit a Recipe</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (submitted)
{
    <div class="alert alert-success">
        <h4>Recipe Submitted!</h4>
        <p>Your recipe "<strong>@submission.Title</strong>" has been added. <a href="recipes/@submission.Category">View it in @submission.Category</a>.</p>
    </div>
    <button class="btn btn-primary" @onclick="Reset">Submit Another</button>
}
else
{
    <EditForm Model="submission" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
        <DataAnnotationsValidator />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="submission.Title" placeholder="e.g. Grandma's Apple Pie" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="submission.Category">
                <option value="">-- Select a category --</option>
                @foreach (var cat in RecipeService.GetCategories())
                {
                    <option value="@cat">@cat</option>
                }
                <option value="Other">Other</option>
            </InputSelect>
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients</label>
            <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="submission.Ingredients" placeholder="One ingredient per line" />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps</label>
            <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="submission.Steps" placeholder="Describe each step on a new line" />
        </div>

        <button type="submit" class="btn btn-success" disabled="@(!IsValid)">Submit Recipe</button>
    </EditForm>
}

@code {
    private RecipeSubmission submission = new();
    private bool submitted;

    private bool IsValid =>
        !string.IsNullOrWhiteSpace(submission.Title) &&
        !string.IsNullOrWhiteSpace(submission.Category) &&
        !string.IsNullOrWhiteSpace(submission.Ingredients) &&
        !string.IsNullOrWhiteSpace(submission.Steps);

    private void HandleSubmit()
    {
        if (!IsValid) return;
        RecipeService.SubmitRecipe(submission);
        submitted = true;
    }

    private void Reset()
    {
        submission = new RecipeSubmission();
        submitted = false;
    }
}
EOF

